UPDATE zw_score
EXAM_ID = #{examId}, STUDENT_ID = #{studentId}, SCORE = #{score},
WHERE SCORE_ID = #{scoreId}

mapper.select:
SELECT s.SCORE_ID, s.EXAM_ID, s.STUDENT_ID, s.SCORE, e.EXAM_NAME, e.SUBJECT_TYPE, sub.CODE_DESC as SUBJECT_TYPE_DESC, e.EXAM_TIME, st.STUDENT_CODE, st.GRA, st.CLA, u.NAME, (SELECT COUNT(*) + 1 FROM zw_score s2 LEFT JOIN g_exam e2 ON s2.EXAM_ID = e2.EXAM_ID LEFT JOIN zw_student st2 ON s2.STUDENT_ID = st2.STUDENT_ID WHERE s2.EXAM_ID = s.EXAM_ID AND e2.SUBJECT_TYPE = e.SUBJECT_TYPE AND st2.CLA = st.CLA AND s2.SCORE > s.SCORE) as CLASS_RANK, (SELECT COUNT(*) + 1 FROM zw_score s2 LEFT JOIN g_exam e2 ON s2.EXAM_ID = e2.EXAM_ID LEFT JOIN zw_student st2 ON s2.STUDENT_ID = st2.STUDENT_ID WHERE s2.EXAM_ID = s.EXAM_ID AND e2.SUBJECT_TYPE = e.SUBJECT_TYPE AND st2.GRA = st.GRA AND s2.SCORE > s.SCORE) as GRADE_RANK FROM zw_score s LEFT JOIN g_exam e ON s.EXAM_ID = e.EXAM_ID LEFT JOIN g_code sub ON e.SUBJECT_TYPE = sub.CODE_ID LEFT JOIN zw_student st ON s.STUDENT_ID = st.STUDENT_ID LEFT JOIN g_user u ON st.USER_ID = u.USER_ID WHERE s.STUDENT_ID = #{param1}
AND s.EXAM_ID = #{param2}
AND e.SUBJECT_TYPE = #{param3}
AND e.EXAM_NAME LIKE CONCAT('%', #{param4}, '%')
ORDER BY e.EXAM_TIME DESC
